from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
from datetime import datetime
from urllib.parse import urlencode, quote
import uuid
import os

app = Flask(__name__, static_folder='.', static_url_path='')
CORS(app, resources={r"/api/*": {"origins": "*"}})

RECIPIENT_ACCOUNT = '12100011-11345707'
RECIPIENT_NAME = 'Zsebeházi Andrea'
RECIPIENT_IBAN = 'HU42121000111134570700000000'

def format_amount_for_payto(value):
    s = '{0:.2f}'.format(value).rstrip('0').rstrip('.')
    return s

def generate_payto_deeplink(amount_str, reference):
    params = {
        'amount': 'HUF:' + amount_str,
        'message': reference,
        'receiver-name': RECIPIENT_NAME
    }
    query = urlencode(params, quote_via=quote, safe='')
    return 'payto://iban/' + RECIPIENT_IBAN + '?' + query

@app.route('/', defaults={'path': ''})
@app.route('/<path:path>')
def catch_all(path):
    if path and os.path.exists(os.path.join(app.static_folder, path)):
        return send_from_directory(app.static_folder, path)
    return send_from_directory(app.static_folder, 'index.html')

@app.route('/api/payment/initiate', methods=['POST'])
def initiate_payment():
    try:
        if not request.is_json:
            return jsonify({'success': False, 'error': 'Content-Type must be application/json'}), 400
        data = request.get_json(silent=False)
        amount_raw = data.get('amount')
        reference_raw = data.get('reference', '')
        if amount_raw is None or str(amount_raw).strip() == '':
            return jsonify({'success': False, 'error': 'Amount is required'}), 400
        amount_clean = str(amount_raw).strip().replace(' ', '').replace(',', '.')
        try:
            amount_value = float(amount_clean)
        except ValueError:
            return jsonify({'success': False, 'error': 'Invalid amount format'}), 400
        if amount_value <= 0:
            return jsonify({'success': False, 'error': 'Amount must be positive'}), 400
        reference = str(reference_raw).strip()
        if not reference:
            return jsonify({'success': False, 'error': 'Reference is required'}), 400
        if len(reference) > 140:
            reference = reference[:140]
        amount_formatted = format_amount_for_payto(amount_value)
        transaction_id = 'ZSEBIBABA-' + datetime.utcnow().strftime('%Y%m%d%H%M%S') + '-' + str(uuid.uuid4())[:8].upper()
        deeplink = generate_payto_deeplink(amount_formatted, reference)
        response = {
            'success': True,
            'transaction_id': transaction_id,
            'recipient': {
                'name': RECIPIENT_NAME,
                'account': RECIPIENT_ACCOUNT,
                'iban': RECIPIENT_IBAN
            },
            'amount': amount_formatted,
            'reference': reference,
            'deeplink': deeplink,
            'redirect_url': deeplink
        }
        return jsonify(response), 200
    except Exception:
        return jsonify({'success': False, 'error': 'Internal server error'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False, threaded=True)

